package com.simplemdm.controller;
import com.simplemdm.exception.GlobalExceptionHandler;import com.simplemdm.repository.mdm.FieldDefinitionRepository;import com.simplemdm.repository.workflow.*;import com.simplemdm.service.system.AuthorizationService;import com.simplemdm.service.workflow.ApprovalService;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.mock;import static org.springframework.http.MediaType.APPLICATION_JSON;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
class WorkflowControllerValidationTest{@Test void submitRequiresExpectedVersionAndNonEmptyData()throws Exception{MockMvc mvc=MockMvcBuilders.standaloneSetup(new WorkflowController(mock(ApprovalRequestRepository.class),mock(ApprovalChangeRepository.class),mock(FieldDefinitionRepository.class),mock(ApprovalService.class),mock(AuthorizationService.class))).setControllerAdvice(new GlobalExceptionHandler()).build();mvc.perform(post("/api/workflow/approvals/submit").contentType(APPLICATION_JSON).content("{\"object_type_id\":1,\"record_id\":2,\"department_id\":3,\"data\":{}}")).andExpect(status().isBadRequest());}}
